import "server-only";

/**
 * Private file storage. Keys are generated by the server (`<purpose>/<yyyy>/<uuid>.<ext>`),
 * never taken from user input. Implementations must never overwrite an existing key.
 * local-storage.ts keeps files on this machine's disk, blob-storage.ts in Vercel Blob.
 */
export interface FileStorage {
  /** Stores a new file; rejects if the key already exists. */
  put(key: string, data: Buffer): Promise<void>;
  /** Reads a file; rejects (ENOENT) if it does not exist. */
  read(key: string): Promise<Buffer>;
  /** Deletes a file; succeeds if it is already gone. */
  remove(key: string): Promise<void>;
  /**
   * A short-lived signed URL the browser can download the file from directly, for files too
   * large to pass through the app (Vercel Blob only; local storage streams every file). With
   * `download`, the file is sent as an attachment rather than shown. Only GET /api/files/[id]
   * calls it, after the access check.
   */
  signedReadUrl?(key: string, options?: { download?: boolean }): Promise<string>;
}
